mapper.select:
SELECT cf.cash_flow_id AS cashFlowId, cf.traded_at AS tradedAt, cf.bank_txn_id AS bankTxnId, cf.type AS type, cf.amount AS amount, cf.depositor_name AS depositorName, cf.bank_memo AS bankMemo, cf.source_type AS sourceType, p.project_id AS projectId, p.name AS projectName, sb.settle_id AS settleId, b.title AS roundName, cf.linked_by AS linkedBy, e.name AS linkedByName, cf.linked_at AS linkedAt, cf.is_excluded AS isExcluded, CASE WHEN cf.settle_block_id IS NULL THEN 'UNLINKED' WHEN sb.deleted_at IS NOT NULL OR b.deleted_at IS NOT NULL THEN 'LINK_BLOCK_DELETED' ELSE 'LINKED' END AS linkStatus FROM cash_flow cf LEFT JOIN settlement_block sb ON sb.settle_id = cf.settle_block_id LEFT JOIN block b ON b.block_id = sb.block_id LEFT JOIN step st ON st.step_id = b.step_id LEFT JOIN project p ON p.project_id = st.project_id AND p.deleted_at IS NULL LEFT JOIN employee e ON e.user_id = cf.linked_by WHERE cf.deleted_at IS NULL AND cf.company_id = #{companyId} AND DATE(cf.traded_at) >= #{startDate} AND DATE(cf.traded_at) <= #{endDate} AND cf.settle_block_id IS NULL AND p.project_id = #{projectId}
AND (cf.bank_memo LIKE CONCAT('%', #{keyword}, '%') OR cf.depositor_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY cf.traded_at DESC

SELECT EXISTS (
SELECT 1 FROM cash_flow
WHERE company_id = #{companyId} AND bank_name = #{bankName} AND traded_at = #{tradedAt}
AND amount = #{amount} AND balance_after IS NULL AND deleted_at IS NULL
)

SELECT EXISTS (
SELECT 1 FROM cash_flow
WHERE company_id = #{companyId} AND bank_name = #{bankName} AND traded_at = #{tradedAt}
AND amount = #{amount} AND balance_after IS NULL AND deleted_at IS NULL
AND cash_flow_id != #{cashFlowId}
)
